/* Sentences built from parts. Each entry: [regex, (match, t) => Spanish]. t() translates a part. */
const T12 = "(\\d{1,2}(?::\\d{2})?\\s?(?:AM|PM|a\\.\\s?m\\.|p\\.\\s?m\\.))";
const T12B = "(\\d{1,2}(?::\\d{2})?\\s?(?:AM|PM|a\\.\\s?m\\.|p\\.\\s?m\\.))";
const ES_PATTERNS = [
  [/^(\d{1,2}(?::\d{2})?) ?(AM|PM)$/, m => `${m[1]} ${m[2] === "AM" ? "a.m." : "p.m."}`],
  [/^(\d{1,2}(?::\d{2})?) ?(a\.m\.|p\.m\.)$/, m => m[0]],
  [/^(Sunrise|Sunset) (.+)$/, (m, t) => `${m[1] === "Sunrise" ? "Amanecer" : "Atardecer"} ${t(m[2])}`],
  // hour bars in Plan: "Today 1 PM: avoid: cold (6°), dark"
  [new RegExp(`^(.+?) ${T12}: (avoid|not ideal|OK|good|great)(?:: (.+))?$`), (m, t) =>
    `${t(m[1])} ${t(m[2])}: ${({ avoid: "evitar", "not ideal": "no ideal", OK: "aceptable", good: "bueno", great: "excelente" })[m[3]]}${m[4] ? ": " + m[4].split(", ").map(REASON).join(", ") : ""}`],
  [new RegExp(`^(.+?) ${T12}$`), (m, t) => `${t(m[1])} ${t(m[2])}`],
  // "Today, 1 PM to 3 PM"
  [new RegExp(`^(.+?), ${T12} to ${T12}$`), (m, t) => `${t(m[1])}, de ${t(m[2])} a ${t(m[3])}`],
  [new RegExp(`^Avoid (today|tomorrow|\\S+) ${T12} to ${T12}$`), (m, t) => `Evitar ${({ today: "hoy", tomorrow: "mañana" })[m[1]] || m[1]} de ${t(m[2])} a ${t(m[3])}`],
  [new RegExp(`^Best time for a walk: (?:(.+?), )?${T12} to ${T12}(\\. Walks, runs.*)?$`), (m, t) => `Mejor hora para caminar: ${m[1] ? t(m[1]) + ", " : ""}de ${t(m[2])} a ${t(m[3])}${m[4] ? ". " + t(m[4].slice(2)) : ""}`],
  [/^Best time for (.+) in Baltimore: (.+), (.+) to (.+)$/, (m, t) => `Mejor hora para ${m[1]} en Baltimore: ${t(m[2])}, de ${t(m[3])} a ${t(m[4])}`],
  [new RegExp(`^Around ${T12}$`), (m, t) => `Alrededor de las ${t(m[1])}`],
  // fragments: the second time sits in its own element ("Today, 1 p.m. to" + "3 p.m.")
  [new RegExp(`^(.+?), ${T12} to$`), (m, t) => `${t(m[1])}, de ${t(m[2])} a`],
  [new RegExp(`^Avoid (today|tomorrow|\\S+) ${T12} to$`), (m, t) => `Evitar ${({ today: "hoy", tomorrow: "mañana" })[m[1]] || m[1]} de ${t(m[2])} a`],
  [new RegExp(`^Best time for a walk: (?:(.+?), )?${T12} to$`), (m, t) => `Mejor hora para caminar: ${m[1] ? t(m[1]) + ", " : ""}de ${t(m[2])} a`],
  [/^Rain likely around$/, () => "Probable lluvia alrededor de las"],
  [new RegExp(`^(.+), Weekdays ${T12} to$`), (m, t) => `${m[1]}, días de semana de ${t(m[2])} a`],
  // Today: priorities with numbers and times
  [/^Rain likely around (.+)$/, (m, t) => `Probable lluvia alrededor de las ${t(m[1])}`],
  [/^Rain likely from about (.+)\. Move things off basement floors and avoid driving through standing water\.$/, (m, t) => `Probable lluvia desde las ${t(m[1])}. Levante las cosas del piso del sótano y no maneje por agua estancada.`],
  [/^Up to a (\d+)% chance in the next 12 hours\. Bring an umbrella\.$/, m => `Hasta ${m[1]}% de probabilidad en las próximas 12 horas. Lleve paraguas.`],
  [/^Windy, up to (\d+) mph$/, m => `Viento de hasta ${m[1]} mph`], [/^Strongest around (.+)\. Secure loose items outside\.$/, (m, t) => `Más fuerte alrededor de las ${t(m[1])}. Asegure los objetos sueltos afuera.`],
  [/^Dangerous heat, feels like (.+)$/, m => `Calor peligroso, sensación de ${m[1]}`], [/^Hot today, feels like (.+)$/, m => `Calor hoy, sensación de ${m[1]}`], [/^Warm, up to (.+)$/, m => `Templado, hasta ${m[1]}`],
  [/^(?:Worst|Hottest) around (.+?)\. Stay somewhere air-conditioned, drink water often, and check on older neighbors\.$/, (m, t) => `Lo peor alrededor de las ${t(m[1])}. Quédese en un lugar con aire acondicionado, tome agua seguido y visite a sus vecinos mayores.`],
  [/^Right now\. Stay somewhere air-conditioned, drink water often, and check on older neighbors\.$/, () => "Ahora mismo. Quédese en un lugar con aire acondicionado, tome agua seguido y visite a sus vecinos mayores."],
  [/^Hottest (?:around (.+?)|right now)\. Drink water, rest in the shade, and keep hard work for the morning\.$/, (m, t) => `${m[1] ? "Más calor alrededor de las " + t(m[1]) : "Más calor ahora"}. Tome agua, descanse a la sombra y deje el trabajo pesado para la mañana.`],
  [/^Code Blue cold expected, wind chill (.+)$/, m => `Se espera frío Código Azul, sensación térmica de ${m[1]}`],
  [/^Coldest around (.+?)\. The city usually declares a Code Blue at this level, which opens every emergency shelter\. Limit time outside; the Shelter Hotline can find you a bed\.$/, (m, t) => `Lo más frío alrededor de las ${t(m[1])}. La ciudad suele declarar Código Azul a este nivel, y entonces abren todos los refugios de emergencia. Limite el tiempo afuera; la línea de refugios puede conseguirle una cama.`],
  [/^Coldest around (.+?), wind chill (.+)$/, (m, t) => `Lo más frío alrededor de las ${t(m[1])}, sensación térmica de ${m[2]}`],
  [/^Coldest around (.+?)\. Wear layers, cover hands and ears, and bring pets inside\.$/, (m, t) => `Lo más frío alrededor de las ${t(m[1])}. Use varias capas, cúbrase manos y orejas, y entre a sus mascotas.`],
  [/^Coldest around (.+?)\. A warm coat helps\.$/, (m, t) => `Lo más frío alrededor de las ${t(m[1])}. Un abrigo ayuda.`],
  [/^Freezing, down to (.+)$/, m => `Helada, hasta ${m[1]}`], [/^Cold, down to (.+)$/, m => `Frío, hasta ${m[1]}`],
  [/^(Very strong|Strong) sun, UV (\d+)$/, m => `Sol ${m[1] === "Strong" ? "fuerte" : "muy fuerte"}, UV ${m[2]}`],
  [/^Unhealthy air, AQI (\d+)$/, m => `Aire dañino, ICA ${m[1]}`], [/^Air is moderate, AQI (\d+)$/, m => `Aire moderado, ICA ${m[1]}`], [/^Clean air, AQI (\d+)$/, m => `Aire limpio, ICA ${m[1]}`],
  [/^The city has declared a Code Blue Extreme Cold Alert through (.+?)\. All emergency shelters are open\. If you or someone you see needs a warm place, call the Shelter Hotline\.$/, m => `La ciudad declaró una Alerta de Frío Extremo Código Azul hasta el ${m[1]}. Todos los refugios de emergencia están abiertos. Si usted o alguien que ve necesita un lugar cálido, llame a la línea de refugios.`],
  [/^The city has declared a Code Red Extreme Heat Alert through (.+?)\. Cooling centers are open\. Stay somewhere cool and check on older neighbors\.$/, m => `La ciudad declaró una Alerta de Calor Extremo Código Rojo hasta el ${m[1]}. Los centros de enfriamiento están abiertos. Quédese en un lugar fresco y visite a sus vecinos mayores.`],
  [/^Code (Blue|Red) is in effect through (.+)$/, m => `Código ${m[1] === "Blue" ? "Azul" : "Rojo"} vigente hasta el ${m[2]}`],
  [/^Last Code (Blue|Red): (.+)\.$/, m => `Último Código ${m[1] === "Blue" ? "Azul" : "Rojo"}: ${m[2]}.`],
  [/^(.+) in effect\.$/, m => `${m[1]}: vigente.`],
  [/^Your block, (.+)$/, m => `Su cuadra, ${m[1]}`], [/^Places near (.+)$/, m => `Lugares cerca de ${m[1]}`],
  [/^(Parks and water fountains|Parks nearby|Community gardens|Markets and parks|Nearest bike lanes and trails|Rec centers, parks and pools) closest to (.+)$/, (m, t) => `${({ "Parks and water fountains": "Parques y fuentes de agua", "Parks nearby": "Parques", "Community gardens": "Huertos comunitarios", "Markets and parks": "Mercados y parques", "Nearest bike lanes and trails": "Ciclovías y senderos", "Rec centers, parks and pools": "Centros recreativos, parques y piscinas" })[m[1]]} más cercanos a ${m[2]}`],
  // Today: hero reason
  [/^The air is (.+?)(, fine for most people)?\.$/, (m, t) => `La calidad del aire es ${t(m[1][0].toUpperCase() + m[1].slice(1)).toLowerCase()}${m[2] ? ", bien para la mayoría" : ""}.`],
  [/^(.+?), clean air( and no rain expected)?\.$/, (m, t) => `${t(m[1])}, aire limpio${m[2] ? " y sin lluvia prevista" : ""}.`],
  [/^Baltimore, (.+)$/, m => `Baltimore, ${m[1]}`],
  // My block summary
  [/^(.+?) is (hotter in summer than most of Baltimore|cooler in summer than most of Baltimore|about average for summer heat)(?: and has (less|more) tree shade than most)?\.$/, m =>
    `${m[1]} es ${({ "hotter in summer than most of Baltimore": "más caliente en verano que la mayor parte de Baltimore", "cooler in summer than most of Baltimore": "más fresco en verano que la mayor parte de Baltimore", "about average for summer heat": "promedio en calor de verano" })[m[2]]}${m[3] ? ` y tiene ${m[3] === "less" ? "menos" : "más"} sombra de árboles que la mayoría` : ""}.`],
  [/^(.+?): (among the hottest areas|hotter than most of the city|about average for baltimore|cooler than most of the city|among the coolest areas) in summer, with (.+)\. See flood risk and the nearest help\.$/, (m, t) =>
    `${m[1]}: ${t(m[2][0].toUpperCase() + m[2].slice(1)).toLowerCase()} en verano, con ${t(m[3][0].toUpperCase() + m[3].slice(1)).toLowerCase()}. Vea el riesgo de inundación y la ayuda más cercana.`],
  [/^(Summer heat|Shade from trees|Health risks|Money and jobs|Housing and energy bills|Getting around and food): (?:score (\d+) of 100|(.+))$/, (m, t) => `${t(m[1])}: ${m[2] ? `puntaje ${m[2]} de 100` : t(m[3])}`],
  [/^(.+): heat, flood risk and help nearby$/, m => `${m[1]}: calor, riesgo de inundación y ayuda cercana`],
  [/^This spot is in FEMA's high-risk flood zone \(zone (\w+)\)\. Flood insurance is usually required with a mortgage, and it's worth having either way\.$/, m => `Este lugar está en la zona de alto riesgo de inundación de FEMA (zona ${m[1]}). Con una hipoteca normalmente se exige seguro contra inundaciones, y conviene tenerlo de todos modos.`],
  [/^Charm City Pulse report for (.+) \(census tract (.+)\), data build (.+?)\. (.+)$/, m => `Informe de Charm City Pulse para ${m[1]} (sector censal ${m[2]}), datos del ${m[3]}. ${m[4]}`],
  // Help: call buttons, directions, opening hours
  [/^Call (.+) at (.+)$/, (m, t) => `Llamar a ${t(m[1])} al ${m[2]}`], [/^Call ([\d-]+)$/, m => `Llamar al ${m[1]}`],
  [/^Directions to (.+)$/, m => `Cómo llegar a ${m[1]}`], [/^Open (.+) website$/, (m, t) => `Abrir el sitio web de ${t(m[1])}`],
  [/^(.+), Regular library hours \(vary by branch\)$/, m => `${m[1]}, horario normal de la biblioteca (varía por sucursal)`],
  [new RegExp(`^(.+), Weekdays ${T12} to ${T12}$`), (m, t) => `${m[1]}, días de semana de ${t(m[2])} a ${t(m[3])}`],
  [/^(.+), Mon[–-]Fri (.+)$/, m => `${m[1]}, lun. a vie. ${m[2]}`],
  [/^Warming center, open on cold days Nov 15 to Mar 15\. (.+)$/, (m, t) => `Centro de calentamiento, abre en días fríos del 15 de nov. al 15 de mar. ${({ "Women and children": "Mujeres y niños", Men: "Hombres", Women: "Mujeres", Families: "Familias", Youth: "Jóvenes" })[m[1]] || m[1]}`],
  [/^(.+), ([\d.]+) mi away$/, m => `${m[1]}, a ${m[2]} mi`],
  [/^(.+), Daily (.+)$/, m => `${m[1]}, todos los días ${m[2]}`],
  [/^Around$/, () => "Alrededor de las"],
  [/^Peak UV: (.+)$/, (m, t) => `UV máximo: ${t(m[1]).toLowerCase()}`],
  [/^(\d{4}) \(Maryland ranking\)$/, m => `${m[1]} (clasificación de Maryland)`], [/^(\d{4}) release \((.+)\)$/, m => `publicación ${m[1]} (${m[2]})`],
  [/^(\d{4}): (.+) → (\d{4}): (.+?)( \(trend\))?$/, m => `${m[1]}: ${m[2]} → ${m[3]}: ${m[4]}${m[5] ? " (tendencia)" : ""}`],
  [/^(up|down) (.+?)( points| years)?$/, m => `${m[1] === "up" ? "sube" : "baja"} ${m[2]}${m[3] ? (m[3] === " points" ? " puntos" : " años") : ""}`], [/^no change$/, () => "sin cambio"],
  [/^Takes SNAP \(EBT\)(?:\. (.+))?$/, m => `Acepta SNAP (EBT)${m[1] ? ". " + ({ Supermarket: "Supermercado", "Super Store": "Hipermercado", "Large Grocery Store": "Tienda de comestibles grande", "Medium Grocery Store": "Tienda de comestibles mediana", "Small Grocery Store": "Tienda de comestibles pequeña", "Combination Grocery/Other": "Comestibles y otros", "Farmers and Markets": "Mercado de agricultores", "Convenience Store": "Tienda de conveniencia", "Specialty Store": "Tienda especializada", "Meat/Poultry Specialty": "Carnicería", "Fruits/Veg Specialty": "Frutas y verduras", "Bakery Specialty": "Panadería", "Seafood Specialty": "Pescadería" }[m[1]] || m[1]) : ""}`],
  [/^Posted (.+?)\.$/, m => `Publicado el ${m[1]}.`],
  [/^Sampling runs May to September\. Last results, (.+):$/, m => `El muestreo es de mayo a septiembre. Últimos resultados, ${m[1]}:`],
  [/^(Boil-water advisory|Water main break|Water service interruption|Water supply notice): (.+)$/, (m, t) => `${t(m[1])}: ${m[2]}`],
  [/^(Bus stop|Light RailLink|Metro SubwayLink), (.+) away$/, (m, t) => `${t(m[1])}, a ${m[2]}`],
  [/^Data build (.+)$/, m => `Datos del ${m[1]}`],
  [/^New neighborhood data published (.+)\. The page has been updated\.$/, m => `Se publicaron nuevos datos del vecindario el ${m[1]}. La página se actualizó.`],
  [/^now (\d+)$/, m => `ahora ${m[1]}`],
  [/^(cold|hot|unhealthy air|very strong sun|windy|dark)(, .+)*$/, m => m[0].split(", ").map(REASON).join(", ")],
];

/* Reasons on the Plan hour bars: "cold (6°)", "unhealthy air (AQI 120)", "very strong sun (UV 9)", "windy (30 mph)", "80% rain chance", "dark" */
function REASON(r) {
  const rc = r.match(/^(\d+)% rain chance$/); if (rc) return `${rc[1]}% de lluvia`;
  const m = r.match(/^(.+?) \((.+)\)$/), w = m ? m[1] : r;
  const M = { cold: "frío", hot: "calor", windy: "viento", dark: "oscuro", "unhealthy air": "aire dañino", "very strong sun": "sol muy fuerte", "strong sun": "sol fuerte", icy: "hielo", humid: "humedad" };
  return (M[w] || w) + (m ? ` (${m[2].replace("AQI", "ICA")})` : "");
}
